45	static void pan_connection_state_cb(void* cookie, profile_connection_state_t state,
46	    bt_address_t* addr, uint8_t local_role,
47	    uint8_t remote_role)
48	{
49	    char addr_str[BT_ADDR_STR_LENGTH] = { 0 };
50	
51	    bt_addr_ba2str(addr, addr_str);
52	    PRINT("%s, addr:%s, state:%d, local_role:%d, remote_role:%d", __func__,
53	        addr_str, state, local_role, remote_role);
54	}
