62	static int connect_cmd(void* handle, int argc, char* argv[])
63	{
64	    uint32_t src_role, dst_role;
65	    bt_address_t addr;
66	
67	    if (argc < 3)
68	        return CMD_PARAM_NOT_ENOUGH;
69	
70	    if (bt_addr_str2ba(argv[0], &addr) < 0)
71	        return CMD_INVALID_ADDR;
72	
73	    dst_role = atoi(argv[1]);
74	    src_role = atoi(argv[2]);
75	    if (bt_pan_connect(handle, &addr, dst_role, src_role) != BT_STATUS_SUCCESS)
76	        return CMD_ERROR;
77	
78	    PRINT("%s, address:%s", __func__, argv[0]);
79	
80	    return CMD_OK;
81	}
82	
83	static int disconnect_cmd(void* handle, int argc, char* argv[])
84	{
85	    bt_address_t addr;
86	
87	    if (argc < 1)
88	        return CMD_PARAM_NOT_ENOUGH;
89	
90	    PRINT("%s, address:%s", __func__, argv[0]);
91	    if (bt_addr_str2ba(argv[0], &addr) < 0)
92	        return CMD_INVALID_ADDR;
93	
94	    bt_pan_disconnect(handle, &addr);
95	
96	    return CMD_OK;
97	}
98	
99	static int dump_cmd(void* handle, int argc, char* argv[])
100	{
101	    return CMD_OK;
102	}
103	
104	static const pan_callbacks_t pan_test_cbs = {
105	    sizeof(pan_callbacks_t),
106	    pan_netif_state_cb,
107	    pan_connection_state_cb,
108	};
109	
110	int pan_command_init(void* handle)
111	{
112	    pan_callbacks = bt_pan_register_callbacks(handle, &pan_test_cbs);
113	
114	    return 0;
115	}
116	
117	void pan_command_uninit(void* handle)
118	{
119	    bt_pan_unregister_callbacks(handle, pan_callbacks);
120	}
121	
122	int pan_command_exec(void* handle, int argc, char* argv[])
123	{
124	    int ret = CMD_USAGE_FAULT;
125	
126	    if (argc > 0)
127	        ret = execute_command_in_table(handle, g_pan_tables, ARRAY_SIZE(g_pan_tables), argc, argv);
128	
129	    if (ret < 0)
130	        usage();
131	
132	    return ret;
133	}

